-- The whole schema. Every surrogate key is a UUIDv7 in a 16-byte BLOB, minted
-- by Go; a nullable id holds NULL for none. Instants are Unix milliseconds
-- UTC, and created_at/modified_at are always written by Go, never defaulted.
-- Tables people create also say which profile created and last changed a
-- row (created_by/modified_by), NULL when no one signed in did. Synced
-- tables carry sync_version; their triggers are generated by
-- internal/replica, never written here.

CREATE TABLE library (
  id BLOB NOT NULL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL CHECK (kind IN ('movies','tv','music','youtube')),
  scan_hour INTEGER NOT NULL DEFAULT 3 CHECK (scan_hour BETWEEN 0 AND 23),
  watch_files INTEGER NOT NULL DEFAULT 1 CHECK (watch_files IN (0,1)),
  last_scanned_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE library_folder (
  id BLOB NOT NULL PRIMARY KEY,
  library_id BLOB NOT NULL REFERENCES library(id) ON DELETE CASCADE,
  path TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL
);

CREATE TABLE item (
  id BLOB NOT NULL PRIMARY KEY,
  library_id BLOB NOT NULL REFERENCES library(id) ON DELETE CASCADE,
  parent_id BLOB REFERENCES item(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('movie','show','season','episode','artist','album','song','channel','video')),
  path TEXT,
  parsed_title TEXT NOT NULL,
  parsed_year INTEGER,
  season_number INTEGER,
  episode_number INTEGER,
  disc_number INTEGER,
  track_number INTEGER,
  artist_id BLOB REFERENCES item(id) ON DELETE SET NULL,
  sort_title TEXT,
  added_at INTEGER NOT NULL,
  kids_content INTEGER CHECK (kids_content IN (0,1)),
  explicit INTEGER CHECK (explicit IN (0,1)),
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  CHECK ((kind IN ('season','episode','album','song','video')) = (parent_id IS NOT NULL)),
  CHECK (kind = 'song' OR artist_id IS NULL)
);

CREATE TABLE item_metadata (
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  source TEXT NOT NULL DEFAULT 'remote' CHECK (source IN ('local','remote')),
  provider TEXT NOT NULL DEFAULT 'tmdb',
  provider_id INTEGER,
  status TEXT NOT NULL DEFAULT 'unmatched' CHECK (status IN ('unmatched','matched')),
  title TEXT,
  overview TEXT,
  release_date TEXT,
  runtime_minutes INTEGER,
  content_rating TEXT,
  poster_path TEXT,
  backdrop_path TEXT,
  fetched_at INTEGER,
  retry_at INTEGER,
  external_id TEXT,
  published_at INTEGER,
  sidecar_stamp INTEGER,
  identity_stamp TEXT,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (item_id, source)
);

CREATE TABLE genre (
  id BLOB NOT NULL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  tmdb_id INTEGER UNIQUE,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE item_genre (
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  genre_id BLOB NOT NULL REFERENCES genre(id) ON DELETE CASCADE,
  source TEXT NOT NULL DEFAULT 'remote' CHECK (source IN ('local','remote')),
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (item_id, genre_id, source)
);

CREATE TABLE person (
  id BLOB NOT NULL PRIMARY KEY,
  tmdb_id INTEGER UNIQUE,
  name TEXT NOT NULL,
  profile_path TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE credit (
  id BLOB NOT NULL PRIMARY KEY,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  person_id BLOB NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('cast','crew')),
  character TEXT,
  job TEXT,
  department TEXT,
  position INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  UNIQUE (item_id, kind, position)
);

-- The TMDB keywords of a movie or show, as its last remote fetch gave them.
CREATE TABLE item_keyword (
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  keyword_id INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (item_id, keyword_id)
);

CREATE TABLE song_release (
  item_id BLOB NOT NULL PRIMARY KEY REFERENCES item(id) ON DELETE CASCADE,
  release_id TEXT,
  release_group_id TEXT
);

CREATE TABLE edition (
  id BLOB NOT NULL PRIMARY KEY,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  tag TEXT,
  runtime_ms INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

-- file_modified_at is the file's own mtime; modified_at is the row's.
CREATE TABLE media_file (
  id BLOB NOT NULL PRIMARY KEY,
  path TEXT NOT NULL UNIQUE,
  size_bytes INTEGER NOT NULL,
  file_modified_at INTEGER NOT NULL,
  container TEXT,
  duration_ms INTEGER,
  bitrate INTEGER,
  probed_at INTEGER,
  previews_failed_for INTEGER,
  missing_at INTEGER,
  probe_failed_at INTEGER,
  probe_error TEXT,
  fingerprint TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE edition_file (
  edition_id BLOB NOT NULL REFERENCES edition(id) ON DELETE CASCADE,
  media_file_id BLOB NOT NULL REFERENCES media_file(id) ON DELETE CASCADE,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (edition_id, media_file_id)
);

CREATE TABLE track (
  id BLOB NOT NULL PRIMARY KEY,
  media_file_id BLOB NOT NULL REFERENCES media_file(id) ON DELETE CASCADE,
  stream_index INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('video','audio','subtitle')),
  codec TEXT NOT NULL,
  profile TEXT,
  level INTEGER,
  language TEXT,
  title TEXT,
  is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0,1)),
  is_forced INTEGER NOT NULL DEFAULT 0 CHECK (is_forced IN (0,1)),
  bitrate INTEGER,
  width INTEGER,
  height INTEGER,
  frame_rate REAL,
  bit_depth INTEGER,
  pixel_format TEXT,
  color_primaries TEXT,
  color_transfer TEXT,
  hdr_format TEXT,
  channels INTEGER,
  channel_layout TEXT,
  sample_rate INTEGER,
  subtitle_is_text INTEGER CHECK (subtitle_is_text IN (0,1)),
  dv_profile INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  UNIQUE (media_file_id, stream_index)
);

CREATE TABLE chapter (
  id BLOB NOT NULL PRIMARY KEY,
  media_file_id BLOB NOT NULL REFERENCES media_file(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  start_ms INTEGER NOT NULL,
  end_ms INTEGER NOT NULL,
  title TEXT,
  thumbnail_path TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  UNIQUE (media_file_id, position)
);

CREATE TABLE seek_preview (
  id BLOB NOT NULL PRIMARY KEY,
  media_file_id BLOB NOT NULL UNIQUE REFERENCES media_file(id) ON DELETE CASCADE,
  dir TEXT NOT NULL,
  interval_ms INTEGER NOT NULL CHECK (interval_ms > 0),
  count INTEGER NOT NULL CHECK (count > 0),
  width INTEGER NOT NULL CHECK (width > 0),
  height INTEGER NOT NULL CHECK (height > 0),
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

-- audio_track_id and burn_track_id are in the dedupe key, where NULLs never
-- collide, so x'' stands for no track.
CREATE TABLE conversion (
  id BLOB NOT NULL PRIMARY KEY,
  media_file_id BLOB NOT NULL REFERENCES media_file(id) ON DELETE CASCADE,
  source_modified_at INTEGER NOT NULL,
  verdict TEXT NOT NULL CHECK (verdict IN ('remux','audio_transcode','video_transcode')),
  video_action TEXT NOT NULL CHECK (video_action IN ('copy','convert')),
  video_codec TEXT NOT NULL DEFAULT '',
  tone_map INTEGER NOT NULL DEFAULT 0 CHECK (tone_map IN (0,1)),
  height INTEGER NOT NULL DEFAULT 0,
  bitrate INTEGER NOT NULL DEFAULT 0,
  audio_track_id BLOB NOT NULL DEFAULT x'',
  audio_action TEXT NOT NULL CHECK (audio_action IN ('copy','convert')),
  audio_channels INTEGER NOT NULL DEFAULT 0,
  burn_track_id BLOB NOT NULL DEFAULT x'',
  container TEXT NOT NULL CHECK (container IN ('mp4','m4a')),
  status TEXT NOT NULL CHECK (status IN ('queued','converting','ready','failed')),
  predicted_bytes INTEGER NOT NULL,
  size_bytes INTEGER,
  error TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  started_at INTEGER,
  finished_at INTEGER,
  UNIQUE (media_file_id, source_modified_at, verdict, video_action, video_codec, tone_map, height, bitrate,
    audio_track_id, audio_action, audio_channels, burn_track_id)
);

CREATE TABLE identity_review (
  id BLOB NOT NULL PRIMARY KEY,
  library_id BLOB NOT NULL REFERENCES library(id) ON DELETE CASCADE,
  item_id BLOB REFERENCES item(id) ON DELETE CASCADE,
  path TEXT,
  reason TEXT NOT NULL CHECK (reason IN ('conflicting_identity','invalid_identity','tied_candidates','conflicting_years',
    'ambiguous_move','no_match','unrecognized')),
  raised_at INTEGER NOT NULL,
  dismissed_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  CHECK ((item_id IS NULL) != (path IS NULL))
);

CREATE TABLE identity_evidence (
  id BLOB NOT NULL PRIMARY KEY,
  review_id BLOB NOT NULL REFERENCES identity_review(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('current','stated','candidate')),
  provider TEXT CHECK (provider IN ('tmdb','tvdb','imdb','musicbrainz')),
  external_id TEXT,
  title TEXT,
  year INTEGER,
  country TEXT,
  path TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  UNIQUE (review_id, position)
);

CREATE TABLE household (
  id BLOB NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  adult_id BLOB NOT NULL UNIQUE REFERENCES account(id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE account (
  id BLOB NOT NULL PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('adult','kid')),
  email TEXT COLLATE NOCASE UNIQUE,
  name TEXT NOT NULL,
  is_admin INTEGER NOT NULL DEFAULT 0 CHECK (is_admin IN (0,1)),
  household_id BLOB REFERENCES household(id) ON DELETE CASCADE,
  password_hash TEXT,
  birthday TEXT,
  pin_hash TEXT,
  pin_failures INTEGER NOT NULL DEFAULT 0,
  pin_locked_until INTEGER,
  filter_mode TEXT NOT NULL DEFAULT 'ratings' CHECK (filter_mode IN ('ratings','allow_list')),
  movie_ceiling TEXT,
  tv_ceiling TEXT,
  revoked_at INTEGER,
  hide_kids_content INTEGER NOT NULL DEFAULT 0 CHECK (hide_kids_content IN (0,1)),
  color TEXT,
  no_autoplay INTEGER NOT NULL DEFAULT 0 CHECK (no_autoplay IN (0,1)),
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  CHECK (kind = 'adult' OR household_id IS NOT NULL),
  CHECK (kind = 'adult' OR (is_admin = 0 AND email IS NULL AND password_hash IS NULL)),
  CHECK (kind = 'kid' OR (movie_ceiling IS NULL AND tv_ceiling IS NULL))
);

CREATE TABLE household_member (
  household_id BLOB NOT NULL REFERENCES household(id) ON DELETE CASCADE,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (household_id, account_id)
);

-- A pair of adults, stored once with the smaller id (bytewise) first.
CREATE TABLE adult_link (
  a_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  b_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  tv INTEGER NOT NULL DEFAULT 0 CHECK (tv IN (0,1)),
  created_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (a_id, b_id),
  CHECK (a_id < b_id)
);

CREATE TABLE profile_offer (
  id BLOB NOT NULL PRIMARY KEY,
  profile_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  household_id BLOB NOT NULL REFERENCES household(id) ON DELETE CASCADE,
  from_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  to_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  UNIQUE (profile_id, to_id)
);

CREATE TABLE account_allow (
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (account_id, item_id)
);

CREATE TABLE join_code (
  id BLOB NOT NULL PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  expires_at INTEGER NOT NULL,
  used_at INTEGER,
  revoked_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL
);

CREATE TABLE device (
  id BLOB NOT NULL PRIMARY KEY,
  token_hash TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  platform TEXT NOT NULL,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  household_id BLOB NOT NULL REFERENCES household(id) ON DELETE CASCADE,
  profile_id BLOB REFERENCES account(id) ON DELETE SET NULL,
  linked INTEGER NOT NULL DEFAULT 0 CHECK (linked IN (0,1)),
  last_seen_at INTEGER,
  locked_at INTEGER,
  revoked_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

CREATE TABLE device_link (
  id BLOB NOT NULL PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  poll_token_hash TEXT NOT NULL UNIQUE,
  device_name TEXT NOT NULL,
  platform TEXT NOT NULL,
  source TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','denied')),
  account_id BLOB REFERENCES account(id) ON DELETE CASCADE,
  household_id BLOB REFERENCES household(id) ON DELETE CASCADE,
  device_id BLOB REFERENCES device(id) ON DELETE SET NULL,
  decided_at INTEGER,
  collected_at INTEGER,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  CHECK ((status = 'pending') = (decided_at IS NULL)),
  CHECK (collected_at IS NULL OR status = 'approved')
);

CREATE TABLE sso_provider (
  id BLOB NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  issuer TEXT NOT NULL,
  client_id TEXT NOT NULL,
  client_secret TEXT,
  required_group TEXT,
  links_by_email INTEGER NOT NULL DEFAULT 0 CHECK (links_by_email IN (0,1)),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL
);

CREATE TABLE account_identity (
  id BLOB NOT NULL PRIMARY KEY,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  provider_id BLOB NOT NULL REFERENCES sso_provider(id) ON DELETE CASCADE,
  subject TEXT NOT NULL,
  email TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  UNIQUE (provider_id, subject),
  UNIQUE (account_id, provider_id)
);

CREATE TABLE playback_session (
  id BLOB NOT NULL PRIMARY KEY,
  device_id BLOB NOT NULL REFERENCES device(id) ON DELETE CASCADE,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  media_file_id BLOB NOT NULL REFERENCES media_file(id) ON DELETE CASCADE,
  position_ms INTEGER NOT NULL DEFAULT 0,
  current_entry INTEGER NOT NULL DEFAULT 0,
  started_at INTEGER NOT NULL,
  ended_at INTEGER,
  stream_key TEXT,
  station INTEGER NOT NULL DEFAULT 0 CHECK (station IN (0,1)),
  moved_to_device_id BLOB REFERENCES device(id) ON DELETE SET NULL,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

CREATE TABLE session_plan_entry (
  session_id BLOB NOT NULL REFERENCES playback_session(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  verdict TEXT NOT NULL CHECK (verdict IN ('direct_play','remux','audio_transcode','video_transcode')),
  video_action TEXT NOT NULL CHECK (video_action IN ('copy','convert')),
  audio_action TEXT NOT NULL CHECK (audio_action IN ('copy','convert')),
  subtitle_action TEXT NOT NULL CHECK (subtitle_action IN ('none','sidecar','convert','burn')),
  bad INTEGER NOT NULL DEFAULT 0 CHECK (bad IN (0,1)),
  bad_reason TEXT,
  audio_track_id BLOB REFERENCES track(id) ON DELETE SET NULL,
  audio_channels INTEGER NOT NULL DEFAULT 0,
  subtitle_track_id BLOB REFERENCES track(id) ON DELETE SET NULL,
  video_codec TEXT NOT NULL DEFAULT '',
  encoder TEXT NOT NULL DEFAULT '' CHECK (encoder IN ('','hardware','software')),
  tone_map INTEGER NOT NULL DEFAULT 0 CHECK (tone_map IN (0,1)),
  top_height INTEGER NOT NULL DEFAULT 0,
  top_bitrate INTEGER NOT NULL DEFAULT 0,
  single_rung INTEGER NOT NULL DEFAULT 1 CHECK (single_rung IN (0,1)),
  floor_rung INTEGER NOT NULL DEFAULT 0 CHECK (floor_rung IN (0,1)),
  ts_segments INTEGER NOT NULL DEFAULT 0 CHECK (ts_segments IN (0,1)),
  PRIMARY KEY (session_id, position)
);

CREATE TABLE throughput_sample (
  id BLOB NOT NULL PRIMARY KEY,
  session_id BLOB NOT NULL REFERENCES playback_session(id) ON DELETE CASCADE,
  at INTEGER NOT NULL,
  measured_bitrate INTEGER NOT NULL,
  buffer_ms INTEGER NOT NULL,
  stall_count INTEGER NOT NULL,
  current_rung INTEGER,
  rung_height INTEGER,
  rung_bitrate INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

-- changed_at is the client's instant of the change, which decides between
-- writers.
CREATE TABLE watch_state (
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  position_ms INTEGER NOT NULL DEFAULT 0,
  watched INTEGER NOT NULL DEFAULT 0 CHECK (watched IN (0,1)),
  play_count INTEGER NOT NULL DEFAULT 0,
  last_played_at INTEGER,
  changed_at INTEGER NOT NULL,
  edition_id BLOB REFERENCES edition(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (account_id, item_id)
);

CREATE TABLE watch_together (
  id BLOB NOT NULL PRIMARY KEY,
  household_id BLOB NOT NULL REFERENCES household(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  playing INTEGER NOT NULL DEFAULT 0 CHECK (playing IN (0,1)),
  position_ms INTEGER NOT NULL DEFAULT 0 CHECK (position_ms >= 0),
  position_at INTEGER NOT NULL,
  paused_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  version INTEGER NOT NULL DEFAULT 1,
  opened_at INTEGER NOT NULL,
  join_by INTEGER NOT NULL,
  ended_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

CREATE TABLE watch_together_member (
  watch_together_id BLOB NOT NULL REFERENCES watch_together(id) ON DELETE CASCADE,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  device_id BLOB NOT NULL REFERENCES device(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('host','guest')),
  joined_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  PRIMARY KEY (watch_together_id, device_id),
  UNIQUE (watch_together_id, role)
);

CREATE TABLE task (
  id BLOB NOT NULL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL,
  interval_seconds INTEGER CHECK (interval_seconds IS NULL OR interval_seconds > 0),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  next_run_at INTEGER,
  run_requested_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

CREATE TABLE task_run (
  id BLOB NOT NULL PRIMARY KEY,
  task_id BLOB NOT NULL REFERENCES task(id) ON DELETE CASCADE,
  status TEXT NOT NULL CHECK (status IN ('running','succeeded','failed')),
  progress REAL NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 1),
  error TEXT,
  summary TEXT,
  started_at INTEGER NOT NULL,
  finished_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

-- session_id and item_id are not references: a line outlives what it names.
CREATE TABLE log_entry (
  id BLOB NOT NULL PRIMARY KEY,
  at INTEGER NOT NULL,
  level TEXT NOT NULL CHECK (level IN ('debug','info','warn','error')),
  source TEXT NOT NULL,
  message TEXT NOT NULL,
  session_id BLOB,
  item_id BLOB,
  ffmpeg_command TEXT,
  transcode_reason TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL
);

-- The server's own row; its id is the constant 1, not a surrogate.
CREATE TABLE server_info (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  name TEXT NOT NULL,
  tasks_paused INTEGER NOT NULL DEFAULT 0 CHECK (tasks_paused IN (0,1)),
  tmdb_key TEXT,
  gravatar INTEGER NOT NULL DEFAULT 0 CHECK (gravatar IN (0,1)),
  metadata_source TEXT NOT NULL DEFAULT 'local' CHECK (metadata_source IN ('local','remote')),
  metadata_mode TEXT NOT NULL DEFAULT 'only' CHECK (metadata_mode IN ('only','preferred')),
  read_ahead_seconds INTEGER NOT NULL DEFAULT 300 CHECK (read_ahead_seconds BETWEEN 30 AND 600),
  max_transcodes INTEGER NOT NULL DEFAULT 3 CHECK (max_transcodes BETWEEN 1 AND 8),
  transcode_cache_cap_bytes INTEGER NOT NULL DEFAULT 20000000000
    CHECK (transcode_cache_cap_bytes BETWEEN 1000000000 AND 1000000000000),
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

-- Clients keep an image for as long as the generation they fetched it under
-- is the server's. It advances when any title, collection or person gains,
-- changes or loses an image, or the metadata settings change which image
-- shows, so a trigger on each table catches every writer.
-- Clients are told `settled`, which follows `generation` only once changes
-- have stopped for a while, so a scan does not move them at every title.
CREATE TABLE artwork_generation (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  generation INTEGER NOT NULL,
  settled INTEGER NOT NULL,
  changed_at INTEGER NOT NULL
);

CREATE TABLE playlist (
  id BLOB NOT NULL PRIMARY KEY,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('movies','tv','music')),
  station_owned INTEGER NOT NULL DEFAULT 0 CHECK (station_owned IN (0,1)),
  last_played_at INTEGER,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE collection (
  id BLOB NOT NULL PRIMARY KEY,
  source TEXT NOT NULL CHECK (source IN ('tmdb','custom')),
  household_id BLOB REFERENCES household(id) ON DELETE CASCADE,
  tmdb_id INTEGER UNIQUE,
  name TEXT NOT NULL,
  overview TEXT,
  poster_path TEXT,
  backdrop_path TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  CHECK (CASE source WHEN 'tmdb' THEN tmdb_id IS NOT NULL AND household_id IS NULL
    ELSE tmdb_id IS NULL AND household_id IS NOT NULL AND overview IS NULL AND poster_path IS NULL AND backdrop_path IS NULL END)
);

CREATE TABLE collection_movie (
  collection_id BLOB NOT NULL REFERENCES collection(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  position INTEGER CHECK (position >= 0),
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (collection_id, item_id)
);

-- An entry is a title or a collection. rank is the entry's fractional
-- order key (playlist/rank.go), compared bytewise, ties by id.
CREATE TABLE playlist_entry (
  id BLOB NOT NULL PRIMARY KEY,
  playlist_id BLOB NOT NULL REFERENCES playlist(id) ON DELETE CASCADE,
  item_id BLOB REFERENCES item(id) ON DELETE CASCADE,
  collection_id BLOB REFERENCES collection(id) ON DELETE CASCADE,
  edition_id BLOB REFERENCES edition(id) ON DELETE CASCADE,
  rank TEXT NOT NULL DEFAULT '',
  added_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  CHECK ((item_id IS NULL) != (collection_id IS NULL))
);

CREATE TABLE playlist_share (
  playlist_id BLOB NOT NULL REFERENCES playlist(id) ON DELETE CASCADE,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  access TEXT NOT NULL CHECK (access IN ('read','write')),
  created_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (playlist_id, account_id)
);

CREATE TABLE playlist_household_share (
  playlist_id BLOB NOT NULL REFERENCES playlist(id) ON DELETE CASCADE,
  household_id BLOB NOT NULL REFERENCES household(id) ON DELETE CASCADE,
  access TEXT NOT NULL CHECK (access IN ('read','write')),
  created_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (playlist_id, household_id)
);

CREATE TABLE station (
  id BLOB NOT NULL PRIMARY KEY,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  playlist_id BLOB NOT NULL REFERENCES playlist(id),
  name TEXT NOT NULL,
  shuffled INTEGER NOT NULL DEFAULT 0 CHECK (shuffled IN (0,1)),
  visibility TEXT NOT NULL CHECK (visibility IN ('private','household','server')),
  rating TEXT,
  timing TEXT NOT NULL DEFAULT 'continuous' CHECK (timing IN ('continuous','half_hour','hour')),
  loop INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE station_day (
  station_id BLOB NOT NULL REFERENCES station(id) ON DELETE CASCADE,
  weekday INTEGER NOT NULL CHECK (weekday BETWEEN 0 AND 6),
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (station_id, weekday)
);

CREATE TABLE station_time (
  id BLOB NOT NULL PRIMARY KEY,
  station_id BLOB NOT NULL REFERENCES station(id) ON DELETE CASCADE,
  from_minute INTEGER NOT NULL CHECK (from_minute BETWEEN 0 AND 1439),
  to_minute INTEGER NOT NULL CHECK (to_minute BETWEEN 0 AND 1439),
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE station_program (
  id BLOB NOT NULL PRIMARY KEY,
  station_id BLOB NOT NULL REFERENCES station(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  edition_id BLOB NOT NULL REFERENCES edition(id) ON DELETE CASCADE,
  entry_id BLOB REFERENCES playlist_entry(id) ON DELETE SET NULL,
  loop INTEGER NOT NULL,
  position INTEGER NOT NULL,
  starts_at INTEGER NOT NULL,
  ends_at INTEGER NOT NULL CHECK (ends_at > starts_at),
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

-- A randomized station's loop in the order it plays. Entry and item are a
-- key into the play order, not references: a key whose row is gone is
-- skipped.
CREATE TABLE station_loop (
  station_id BLOB NOT NULL REFERENCES station(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  entry_id BLOB NOT NULL,
  item_id BLOB NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (station_id, position)
);

-- The custom image the owner of a playlist or a station set, one at most
-- each: a JPEG the server made of an upload or a fetched link, or a title's
-- artwork by reference. Ids are never reused, since clients cache by them.
CREATE TABLE cover (
  id BLOB NOT NULL PRIMARY KEY,
  playlist_id BLOB UNIQUE REFERENCES playlist(id) ON DELETE CASCADE,
  station_id BLOB UNIQUE REFERENCES station(id) ON DELETE CASCADE,
  item_id BLOB REFERENCES item(id) ON DELETE CASCADE,
  backdrop INTEGER NOT NULL DEFAULT 0 CHECK (backdrop IN (0,1)),
  jpeg BLOB,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  CHECK ((playlist_id IS NULL) != (station_id IS NULL)),
  CHECK ((item_id IS NULL) != (jpeg IS NULL))
);

CREATE TABLE download (
  id BLOB NOT NULL PRIMARY KEY,
  device_id BLOB NOT NULL REFERENCES device(id) ON DELETE CASCADE,
  account_id BLOB NOT NULL REFERENCES account(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  edition_id BLOB REFERENCES edition(id) ON DELETE CASCADE,
  media_file_id BLOB NOT NULL REFERENCES media_file(id) ON DELETE CASCADE,
  conversion_id BLOB REFERENCES conversion(id) ON DELETE CASCADE,
  quality TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0
);

-- A seasonal label whose movies and shows surface around an anchor: a
-- holiday of the table built into the server, or a month and day.
CREATE TABLE occasion (
  id BLOB NOT NULL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  holiday TEXT,
  month INTEGER CHECK (month BETWEEN 1 AND 12),
  day INTEGER CHECK (day BETWEEN 1 AND 31),
  days_before INTEGER NOT NULL CHECK (days_before >= 0),
  days_after INTEGER NOT NULL CHECK (days_after >= 0),
  color1 TEXT,
  color2 TEXT,
  color3 TEXT,
  created_at INTEGER NOT NULL,
  modified_at INTEGER NOT NULL,
  created_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  modified_by BLOB REFERENCES account(id) ON DELETE SET NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  CHECK ((holiday IS NULL) = (month IS NOT NULL) AND (month IS NULL) = (day IS NULL))
);

-- Members are the movies and shows carrying any of an occasion's keywords
-- or added by hand, less those removed by hand.
CREATE TABLE occasion_keyword (
  occasion_id BLOB NOT NULL REFERENCES occasion(id) ON DELETE CASCADE,
  keyword_id INTEGER NOT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (occasion_id, keyword_id)
);

CREATE TABLE occasion_item (
  occasion_id BLOB NOT NULL REFERENCES occasion(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (occasion_id, item_id)
);

CREATE TABLE occasion_exclusion (
  occasion_id BLOB NOT NULL REFERENCES occasion(id) ON DELETE CASCADE,
  item_id BLOB NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (occasion_id, item_id)
);

CREATE TABLE occasion_phrase (
  occasion_id BLOB NOT NULL REFERENCES occasion(id) ON DELETE CASCADE,
  phrase TEXT NOT NULL COLLATE NOCASE CHECK (length(phrase) BETWEEN 1 AND 60),
  sync_version INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (occasion_id, phrase)
);

-- Holiday occasions the server gives their holiday's built-in phrases and
-- colors once, at its next start.
CREATE TABLE occasion_seed (
  occasion_id BLOB NOT NULL PRIMARY KEY REFERENCES occasion(id) ON DELETE CASCADE
);

-- Client sync bookkeeping. The clock moves once for every change a replica
-- would see; each synced row carries the clock value of its last change
-- and each deletion leaves a tombstone at its own.
CREATE TABLE sync_clock (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  version INTEGER NOT NULL,
  -- the version of the latest change to which rows some household sees
  scope_version INTEGER NOT NULL,
  -- the highest tombstone version purged
  purged_version INTEGER NOT NULL,
  -- the server release that last installed the triggers
  release TEXT NOT NULL
);

-- A deleted row's primary key, its parts in k1 to k3 and unused parts 0.
-- The parts have no affinity, so a key keeps its type: an id part is its
-- 16 bytes.
CREATE TABLE sync_tombstone (
  tbl TEXT NOT NULL,
  k1 BLOB NOT NULL,
  k2 BLOB NOT NULL DEFAULT 0,
  k3 BLOB NOT NULL DEFAULT 0,
  version INTEGER NOT NULL,
  at INTEGER NOT NULL,
  PRIMARY KEY (tbl, k1, k2, k3)
);

-- A replayed client action, kept so a retry answers the same result. uuid
-- is the client's action id, of any UUID version.
CREATE TABLE sync_action (
  device_id BLOB NOT NULL REFERENCES device(id) ON DELETE CASCADE,
  uuid TEXT NOT NULL CHECK (length(uuid) = 36),
  result TEXT NOT NULL CHECK (result IN ('accepted','rejected')),
  code TEXT,
  processed_at INTEGER NOT NULL,
  PRIMARY KEY (device_id, uuid)
);

-- An id is not the rowid, so an index whose queries order or page by id
-- after its columns names id last.
